  margin-bottom: 1rem;
}
.brand-banner-sub {
  font-size: clamp(.95rem, 2vw, 1.15rem);
  color: var(--color-text-secondary);
  max-width: 560px;
  margin-inline: auto;
  margin-bottom: 2.5rem;
}

/* ─── Trust Badges ───────────────────────────────────────────── */
#trust {
  padding-block: 3rem;
}
.trust-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1.5rem;
}
.trust-item {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 1.25rem;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
}
.trust-icon {
  font-size: 1.75rem;
  flex-shrink: 0;
  line-height: 1;
}
.trust-text strong {
  display: block;
  font-size: .9rem;
  font-weight: 600;
  margin-bottom: .15rem;
}
.trust-text span {
  font-size: .8rem;
  color: var(--color-text-secondary);
}

/* ─── Newsletter ─────────────────────────────────────────────── */
#newsletter {
  padding-block: 4rem;
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}
@media (max-width: 700px) {
  .newsletter-inner { grid-template-columns: 1fr; gap: 2rem; }
}
.newsletter-heading {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.2;
  margin-bottom: .75rem;
}
.newsletter-sub {
  font-size: .95rem;
  color: var(--color-text-secondary);
  line-height: 1.6;
}
.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: .75rem;
}
.form-row {
  display: flex;
  gap: .75rem;
}
@media (max-width: 480px) { .form-row { flex-direction: column; } }
.email-input {
  flex: 1;
  padding: .75rem 1rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
