.footer-bottom {
  border-top: 1px solid var(--color-border);
  padding-top: 1.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  font-size: .8rem;
  color: var(--color-text-tertiary);
}
.footer-bottom a {
  text-decoration: none;
  color: var(--color-text-tertiary);
  transition: color var(--transition);
}
.footer-bottom a:hover { color: var(--color-text-secondary); }

/* ─── Cart Drawer ────────────────────────────────────────────── */
.drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.6);
  backdrop-filter: blur(4px);
  z-index: 300;
  opacity: 0;
  visibility: hidden;
  transition: opacity .25s ease, visibility .25s ease;
}
.drawer-overlay[data-open="true"] { opacity: 1; visibility: visible; }

.cart-drawer {
  position: fixed;
  top: 0; right: 0; bottom: 0;
  width: min(420px, 95vw);
  background: var(--color-surface);
  border-left: 1px solid var(--color-border);
  z-index: 301;
  display: flex;
  flex-direction: column;
  transform: translateX(100%);
  transition: transform .3s cubic-bezier(.4,0,.2,1);
}
.cart-drawer[data-open="true"] { transform: translateX(0); }

.drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--color-border);
}
.drawer-title {
  font-size: 1.1rem;
  font-weight: 700;
}
.drawer-close {
  width: 2rem; height: 2rem;
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: var(--color-text-secondary);
  font-size: 1.25rem;
  transition: background var(--transition), color var(--transition);
}
.drawer-close:hover { background: var(--color-surface-2); color: var(--color-text-primary); }

.cart-items {
  flex: 1;
  overflow-y: auto;
  padding: 1.25rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.cart-item {
  display: flex;
  gap: 1rem;
  padding: .75rem;
  background: var(--color-surface-2);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
}
.cart-item-icon {
  font-size: 2.25rem;
  flex-shrink: 0;
  width: 3.5rem; height: 3.5rem;
  background: var(--color-surface-3);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
}
.cart-item-info { flex: 1; min-width: 0; }
.cart-item-name { font-size: .9rem; font-weight: 600; line-height: 1.3; }
.cart-item-price { font-size: .85rem; color: var(--color-text-secondary); margin-top: .25rem; }
.cart-item-remove {
  font-size: .75rem; color: var(--color-text-tertiary);
  transition: color var(--transition);
  align-self: flex-start;
  margin-top: .1rem;
}
.cart-item-remove:hover { color: var(--color-danger); }

.cart-empty {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: .75rem;
  color: var(--color-text-tertiary);
  padding: 2rem;
  text-align: center;
}
.cart-empty-icon { font-size: 3rem; }
.cart-empty p { font-size: .9rem; }

.drawer-footer {
  padding: 1.25rem 1.5rem;
  border-top: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  gap: .75rem;
}
.cart-total {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
}
.cart-total-amount { font-size: 1.2rem; color: var(--color-text-primary); }

/* ─── Live region ────────────────────────────────────────────── */
#live-region {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
}

/* ─── Forced colors ──────────────────────────────────────────── */
@media (forced-colors: active) {
  .btn-primary { background: ButtonText; color: ButtonFace; border-color: ButtonText; }
  .cart-badge { background: Highlight; color: HighlightText; }
  .product-badge { forced-color-adjust: none; }
  :focus-visible { outline-color: Highlight; }
}

/* ─── Reduced motion ─────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    transition-duration: .01ms !important;
    scroll-behavior: auto !important;
  }
}
