:root {
  --color-bg:          #0d0d0f;
  --color-surface:     #16161a;
  --color-surface-2:   #1e1e24;
  --color-surface-3:   #28282f;
  --color-border:      #2e2e38;
  --color-accent:      #e8c14b;
  --color-accent-dim:  #b8983a;
  --color-accent-text: #0d0d0f;
  --color-text-primary:   #f0eff4;
  --color-text-secondary: #9898a8;
  --color-text-tertiary:  #62626f;
  --color-danger:      #e85b5b;
  --color-success:     #4cba7f;

  --radius-sm:  4px;
  --radius-md:  8px;
  --radius-lg:  16px;
  --radius-xl:  24px;

  --shadow-sm:  0 1px 3px rgba(0,0,0,.5);
  --shadow-md:  0 4px 16px rgba(0,0,0,.6);
  --shadow-lg:  0 12px 40px rgba(0,0,0,.7);

  --font-sans: 'Inter', system-ui, sans-serif;
  --font-display: 'Playfair Display', Georgia, serif;

  --transition: 180ms ease;
}

/* ─── Reset & Base ───────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  background: var(--color-bg);
  color: var(--color-text-primary);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
}

img { max-width: 100%; display: block; }
a { color: inherit; }
ul, ol { list-style: none; }
button { font: inherit; cursor: pointer; border: none; background: none; }

/* ─── Skip Link ──────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-accent);
  color: var(--color-accent-text);
  font-weight: 700;
  border-radius: var(--radius-sm);
  z-index: 9999;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ─── Focus visible ──────────────────────────────────────────── */
:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ─── Utility ────────────────────────────────────────────────── */
.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
}

.container {
  max-width: 1280px;
  margin-inline: auto;
  padding-inline: clamp(1rem, 4vw, 2.5rem);
}

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.section-title {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-text-primary);
}

.section-title span {
  color: var(--color-accent);
}

.view-all {
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-accent);
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: .3em;
  transition: color var(--transition), gap var(--transition);
  white-space: nowrap;
}
.view-all:hover { color: var(--color-accent-dim); gap: .55em; }
.view-all::after { content: '→'; }

/* ─── Announcement Bar ───────────────────────────────────────── */
#announcement-bar {
  background: var(--color-accent);
  color: var(--color-accent-text);
  text-align: center;
  padding: .5rem 1rem;
  font-size: .875rem;
  font-weight: 600;
  letter-spacing: .02em;
}

/* ─── Site Header ────────────────────────────────────────────── */
#site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,15,.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 1rem;
  padding-block: .875rem;
}

.site-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -.03em;
  text-decoration: none;
  color: var(--color-text-primary);
  white-space: nowrap;
}
