  --radius-lg:  16px;
  --radius-xl:  24px;

  --shadow-sm:  0 1px 3px rgba(0,0,0,.5);
  --shadow-md:  0 4px 16px rgba(0,0,0,.6);
  --shadow-lg:  0 12px 40px rgba(0,0,0,.7);

  --font-sans: 'Inter', system-ui, sans-serif;
  --font-display: 'Playfair Display', Georgia, serif;

  --transition: 180ms ease;
}

/* ─── Reset & Base ───────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  background: var(--color-bg);
  color: var(--color-text-primary);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
}

img { max-width: 100%; display: block; }
a { color: inherit; }
ul, ol { list-style: none; }
button { font: inherit; cursor: pointer; border: none; background: none; }

/* ─── Skip Link ──────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-accent);
  color: var(--color-accent-text);
  font-weight: 700;
  border-radius: var(--radius-sm);
  z-index: 9999;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ─── Focus visible ──────────────────────────────────────────── */
:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ─── Utility ────────────────────────────────────────────────── */
.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
}

.container {
  max-width: 1280px;
  margin-inline: auto;
  padding-inline: clamp(1rem, 4vw, 2.5rem);
}

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.section-title {
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-text-primary);
}

.section-title span {
  color: var(--color-accent);
}

.view-all {
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-accent);
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: .3em;
  transition: color var(--transition), gap var(--transition);
  white-space: nowrap;
}
.view-all:hover { color: var(--color-accent-dim); gap: .55em; }
.view-all::after { content: '→'; }

/* ─── Announcement Bar ───────────────────────────────────────── */
#announcement-bar {
  background: var(--color-accent);
  color: var(--color-accent-text);
  text-align: center;
  padding: .5rem 1rem;
  font-size: .875rem;
  font-weight: 600;
  letter-spacing: .02em;
}

/* ─── Site Header ────────────────────────────────────────────── */
#site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,15,.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 1rem;
  padding-block: .875rem;
}

.site-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -.03em;
  text-decoration: none;
  color: var(--color-text-primary);
  white-space: nowrap;
}
.site-logo em {
  color: var(--color-accent);
  font-style: normal;
}

.primary-nav { justify-self: center; }
.primary-nav ul {
  display: flex;
  gap: clamp(.75rem, 2vw, 2rem);
}
.primary-nav a {
  font-size: .9rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  text-decoration: none;
  transition: color var(--transition);
  padding-block: .25rem;
  position: relative;
}
.primary-nav a::after {
  content: '';
  position: absolute;
  bottom: -2px; left: 0; right: 0;
  height: 2px;
  background: var(--color-accent);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.primary-nav a:hover,
.primary-nav a[aria-current="page"] { color: var(--color-text-primary); }
.primary-nav a:hover::after,
.primary-nav a[aria-current="page"]::after { transform: scaleX(1); }

.header-actions {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: .5rem;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: var(--radius-md);
  color: var(--color-text-secondary);
  transition: background var(--transition), color var(--transition);
  position: relative;
}
.icon-btn:hover,
.icon-btn:focus-visible {
  background: var(--color-surface-2);
  color: var(--color-text-primary);
}

.cart-badge {
  position: absolute;
  top: 2px; right: 2px;
  min-width: 1.1rem;
  height: 1.1rem;
  padding: 0 .25rem;
  background: var(--color-accent);
  color: var(--color-accent-text);
  font-size: .65rem;
  font-weight: 700;
  border-radius: 99px;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.menu-toggle { display: none; }

/* ─── Mobile nav ─────────────────────────────────────────────── */
@media (max-width: 768px) {
  .header-inner { grid-template-columns: 1fr auto; }
  .primary-nav {
    position: fixed;
    inset: 0 0 0 30%;
    background: var(--color-surface);
    border-left: 1px solid var(--color-border);
    padding: 5rem 2rem 2rem;
    flex-direction: column;
    transform: translateX(100%);
    transition: transform .28s ease;
    z-index: 200;
    overflow-y: auto;
    display: block;
  }
  .primary-nav[data-open="true"] { transform: translateX(0); }
  .primary-nav ul { flex-direction: column; gap: .25rem; }
  .primary-nav a { font-size: 1.1rem; display: block; padding: .6rem 0; }
  .menu-toggle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: var(--radius-md);
    color: var(--color-text-secondary);
    z-index: 201;
  }
}

/* ─── Hero ───────────────────────────────────────────────────── */
#hero {
  position: relative;
  overflow: hidden;
  min-height: clamp(480px, 70vh, 760px);
  display: flex;
  align-items: center;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 80% at 110% 50%, rgba(232,193,75,.12) 0%, transparent 60%),
    radial-gradient(ellipse 60% 60% at -10% 60%, rgba(100,80,200,.1) 0%, transparent 55%),
    linear-gradient(160deg, #0d0d0f 0%, #131318 50%, #0a0a0c 100%);
}

.hero-grid-overlay {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(232,193,75,.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(232,193,75,.04) 1px, transparent 1px);
  background-size: 60px 60px;
  mask-image: radial-gradient(ellipse 80% 80% at 50% 50%, black 30%, transparent 100%);
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 680px;
  padding-block: 4rem;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 1.25rem;
}
.hero-eyebrow::before {
  content: '';
  width: 2rem;
  height: 2px;
  background: var(--color-accent);
}

.hero-heading {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -.03em;
  margin-bottom: 1.25rem;
}
.hero-heading em {
  font-style: italic;
  color: var(--color-accent);
}

.hero-subtext {
  font-size: clamp(1rem, 2vw, 1.15rem);
  color: var(--color-text-secondary);
  max-width: 500px;
  margin-bottom: 2.25rem;
  line-height: 1.7;
}

.hero-cta {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

/* ─── Buttons ────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .5em;
  padding: .75rem 1.75rem;
  border-radius: var(--radius-md);
  font-size: .95rem;
  font-weight: 600;
  text-decoration: none;
  transition: background var(--transition), color var(--transition),
              transform var(--transition), box-shadow var(--transition);
  white-space: nowrap;
  cursor: pointer;
  border: 2px solid transparent;
}
.btn:active { transform: scale(.97); }

.btn-primary {
  background: var(--color-accent);
  color: var(--color-accent-text);
  box-shadow: 0 4px 24px rgba(232,193,75,.25);
}
.btn-primary:hover {
  background: var(--color-accent-dim);
  box-shadow: 0 6px 32px rgba(232,193,75,.35);
}

.btn-outline {
  background: transparent;
  color: var(--color-text-primary);
  border-color: var(--color-border);
}
.btn-outline:hover {
  background: var(--color-surface-2);
  border-color: var(--color-text-secondary);
}

.btn-sm {
  padding: .5rem 1.1rem;
  font-size: .85rem;
}

/* ─── Category Strip ─────────────────────────────────────────── */
#categories {
  padding-block: 2rem;
  border-bottom: 1px solid var(--color-border);
}
.category-list {
  display: flex;
  gap: clamp(.75rem, 2vw, 1.5rem);
  overflow-x: auto;
  padding-bottom: .25rem;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.category-list::-webkit-scrollbar { display: none; }

.category-chip {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .5rem;
  padding: .75rem 1.25rem;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  text-decoration: none;
  color: var(--color-text-secondary);
  font-size: .85rem;
  font-weight: 500;
  transition: border-color var(--transition), color var(--transition),
              background var(--transition), transform var(--transition);
}
.category-chip:hover, .category-chip[aria-current="true"] {
  background: var(--color-surface-2);
  border-color: var(--color-accent);
  color: var(--color-text-primary);
  transform: translateY(-2px);
}
.category-chip .chip-icon {
  font-size: 1.4rem;
  line-height: 1;
}

/* ─── Featured Products ──────────────────────────────────────── */
#featured-products {
  padding-block: 4rem;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 260px), 1fr));
  gap: 1.5rem;
}

/* ─── Product Card ───────────────────────────────────────────── */
.product-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), transform var(--transition),
              box-shadow var(--transition);
  position: relative;
}
.product-card:hover {
  border-color: var(--color-surface-3);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.product-image-wrap {
  position: relative;
  aspect-ratio: 4/3;
  overflow: hidden;
  background: var(--color-surface-2);
}

.product-image-wrap .product-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  background: var(--color-surface-2);
  transition: transform .4s ease;
}
.product-card:hover .product-placeholder { transform: scale(1.06); }

.product-badge {
  position: absolute;
  top: .75rem;
  left: .75rem;
  padding: .25rem .6rem;
  border-radius: var(--radius-sm);
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  line-height: 1;
}
.badge-new { background: var(--color-accent); color: var(--color-accent-text); }
.badge-sale { background: var(--color-danger); color: #fff; }
.badge-bestseller { background: var(--color-success); color: #fff; }

.wishlist-btn {
  position: absolute;
  top: .75rem;
  right: .75rem;
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  background: rgba(13,13,15,.7);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-secondary);
  font-size: 1rem;
  transition: background var(--transition), color var(--transition),
              transform var(--transition);
}
.wishlist-btn:hover { background: var(--color-surface); color: var(--color-danger); transform: scale(1.15); }
.wishlist-btn[aria-pressed="true"] { color: var(--color-danger); }

.product-body {
  padding: 1rem 1.25rem;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: .5rem;
}

.product-category {
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-accent);
}

.product-name {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--color-text-primary);
}

.product-rating {
  display: flex;
  align-items: center;
  gap: .4rem;
  font-size: .8rem;
  color: var(--color-text-secondary);
}
.stars { color: var(--color-accent); letter-spacing: .05em; }

.product-price-row {
  display: flex;
  align-items: baseline;
  gap: .6rem;
  margin-top: auto;
}
.price-current {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--color-text-primary);
}
.price-original {
  font-size: .9rem;
  color: var(--color-text-tertiary);
  text-decoration: line-through;
}
.price-save {
  font-size: .78rem;
  font-weight: 600;
  color: var(--color-danger);
}

.add-to-cart-btn {
  margin-top: .75rem;
  width: 100%;
  padding: .65rem;
  background: var(--color-surface-3);
  color: var(--color-text-primary);
  border-radius: var(--radius-md);
  font-size: .875rem;
  font-weight: 600;
  transition: background var(--transition), color var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .5em;
}
.add-to-cart-btn:hover {
  background: var(--color-accent);
  color: var(--color-accent-text);
}
.add-to-cart-btn[aria-label*="Added"] {
  background: var(--color-success);
  color: #fff;
}

/* ─── Deals Section ──────────────────────────────────────────── */
#deals {
  padding-block: 4rem;
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

@media (max-width: 640px) { .deals-grid { grid-template-columns: 1fr; } }

.deal-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 280px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 2rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  transition: transform var(--transition), box-shadow var(--transition);
}
.deal-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-lg); }

.deal-card--featured {
  grid-row: span 2;
  min-height: 480px;
}
@media (max-width: 640px) { .deal-card--featured { min-height: 280px; grid-row: auto; } }

.deal-bg-emoji {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 8rem;
  opacity: .12;
  pointer-events: none;
  user-select: none;
}

.deal-card-1 { background: linear-gradient(135deg, #1a1025 0%, #0f0f1a 100%); }
.deal-card-2 { background: linear-gradient(135deg, #0f1a14 0%, #0a1210 100%); }
.deal-card-3 { background: linear-gradient(135deg, #1a1208 0%, #120e07 100%); }

.deal-tag {
  display: inline-flex;
  align-items: center;
  padding: .3rem .8rem;
  border-radius: var(--radius-xl);
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  margin-bottom: 1rem;
  width: fit-content;
}
.deal-tag--flash { background: rgba(232,91,91,.15); color: #ff7a7a; border: 1px solid rgba(232,91,91,.3); }
.deal-tag--weekly { background: rgba(76,186,127,.15); color: #5de09c; border: 1px solid rgba(76,186,127,.3); }
.deal-tag--bundle { background: rgba(232,193,75,.15); color: var(--color-accent); border: 1px solid rgba(232,193,75,.3); }

.deal-title {
  font-family: var(--font-display);
  font-size: clamp(1.2rem, 2.5vw, 1.75rem);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: .5rem;
}

.deal-desc {
  font-size: .875rem;
  color: var(--color-text-secondary);
  margin-bottom: 1.25rem;
  line-height: 1.5;
}

.deal-countdown {
  display: flex;
  gap: .5rem;
  margin-bottom: 1.25rem;
  flex-wrap: wrap;
}
.countdown-unit {
  background: rgba(0,0,0,.4);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: .4rem .65rem;
  text-align: center;
  min-width: 3rem;
}
.countdown-num {
  display: block;
  font-size: 1.25rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  color: var(--color-accent);
}
.countdown-label {
  display: block;
  font-size: .6rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-text-tertiary);
  margin-top: .2rem;
}

.deal-discount {
  position: absolute;
  top: 1.25rem;
  right: 1.25rem;
  width: 3.5rem;
  height: 3.5rem;
  background: var(--color-danger);
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: .65rem;
  font-weight: 700;
  text-transform: uppercase;
  line-height: 1.1;
  color: #fff;
  letter-spacing: .02em;
}
.deal-discount strong { font-size: 1rem; }

/* ─── Editorial ──────────────────────────────────────────────── */
#editorial {
  padding-block: 4rem;
}

.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1.5rem;
}
@media (max-width: 900px) { .editorial-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 560px) { .editorial-grid { grid-template-columns: 1fr; } }

.editorial-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition), transform var(--transition),
              box-shadow var(--transition);
}
.editorial-card:hover {
  border-color: var(--color-surface-3);
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}
.editorial-card--hero {
  grid-column: span 2;
}
@media (max-width: 900px) {
  .editorial-card--hero { grid-column: span 2; }
}
@media (max-width: 560px) {
  .editorial-card--hero { grid-column: span 1; }
}

.editorial-image {
  aspect-ratio: 16/9;
  background: var(--color-surface-2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
  overflow: hidden;
  position: relative;
  transition: transform .5s ease;
}
.editorial-card--hero .editorial-image { aspect-ratio: 21/9; font-size: 7rem; }
.editorial-card:hover .editorial-image { transform: scale(1.03); }

.editorial-image-inner {
  transition: transform .5s ease;
  line-height: 1;
}

.editorial-body {
  padding: 1.25rem 1.5rem 1.5rem;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.editorial-tag {
  display: inline-block;
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: .5rem;
}

.editorial-title {
  font-family: var(--font-display);
  font-size: clamp(1rem, 2vw, 1.25rem);
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: .5rem;
  color: var(--color-text-primary);
}

.editorial-excerpt {
  font-size: .875rem;
  color: var(--color-text-secondary);
  line-height: 1.6;
  flex: 1;
  margin-bottom: 1.25rem;
}

.editorial-meta {
  display: flex;
  align-items: center;
  gap: .75rem;
  font-size: .78rem;
  color: var(--color-text-tertiary);
}
.editorial-meta time { font-variant-numeric: tabular-nums; }
.editorial-meta-sep { color: var(--color-border); }

.editorial-link {
  display: inline-flex;
  align-items: center;
  gap: .4em;
  font-size: .85rem;
  font-weight: 600;
  color: var(--color-accent);
  text-decoration: none;
  margin-top: 1rem;
  transition: gap var(--transition), color var(--transition);
}
