        ${product.badge ? `<span class="product-badge ${badgeClass}" aria-label="${product.badgeLabel}">${product.badgeLabel}</span>` : ''}
        <button
          class="wishlist-btn"
          aria-label="${inWishlist ? 'Remove from wishlist' : 'Add to wishlist'}: ${product.name}"
          aria-pressed="${inWishlist}"
          data-wishlist-id="${product.id}"
