            ${product.rating} (${product.reviews})
          </span>
        </div>
        <div class="product-price-row">
          <span class="price-current">${formatPrice(product.price)}</span>
          ${product.originalPrice ? `
            <span class="price-original" aria-label="Was ${formatPrice(product.originalPrice)}">${formatPrice(product.originalPrice)}</span>
            <span class="price-save" aria-label="Save ${saveAmt}%">−${saveAmt}%</span>
