function CartItem(item) {
  return `
    <div class="cart-item" role="listitem">
      <div class="cart-item-icon" aria-hidden="true">${item.icon}</div>
      <div class="cart-item-info">
        <p class="cart-item-name">${item.name}</p>
        <p class="cart-item-price">${formatPrice(item.price)}</p>
      </div>
      <button
        class="cart-item-remove"
        aria-label="Remove ${item.name} from cart"
        data-remove-cart="${item.id}"
      >✕</button>
    </div>
  `;
}

// ─── Render functions ──────────────────────────────────────────

function renderProducts() {
  const grid = document.getElementById('product-grid');
  if (!grid) return;
  grid.innerHTML = products.map(ProductCard).join('');
}

function renderCart() {
  const cartItems = document.getElementById('cart-items');
  const cartEmpty = document.getElementById('cart-empty');
  const cartTotalEl = document.getElementById('cart-total-amount');

  if (!cartItems) return;

  if (state.cart.length === 0) {
    cartItems.innerHTML = '';
    if (cartEmpty) cartEmpty.hidden = false;
    if (cartTotalEl) cartTotalEl.textContent = '$0';
    return;
  }

  if (cartEmpty) cartEmpty.hidden = true;
  cartItems.setAttribute('role', 'list');
  cartItems.innerHTML = state.cart.map(CartItem).join('');

  const total = state.cart.reduce((sum, item) => sum + item.price, 0);
  if (cartTotalEl) cartTotalEl.textContent = formatPrice(total);
}

function updateCartBadge() {
  const badge = document.getElementById('cart-badge');
  if (!badge) return;
  badge.textContent = state.cart.length;
  badge.hidden = state.cart.length === 0;
}

function announce(msg) {
  const region = document.getElementById('live-region');
  if (!region) return;
  region.textContent = '';
  requestAnimationFrame(() => { region.textContent = msg; });
}

// ─── Cart drawer ───────────────────────────────────────────────

function openCart() {
  state.cartOpen = true;
  const drawer = document.getElementById('cart-drawer');
  const overlay = document.getElementById('drawer-overlay');
  drawer.dataset.open = 'true';
  overlay.dataset.open = 'true';
  drawer.removeAttribute('hidden');
  overlay.removeAttribute('hidden');
  document.body.style.overflow = 'hidden';
  // Focus the close button
  const closeBtn = document.getElementById('cart-close');
  if (closeBtn) closeBtn.focus();
  renderCart();
}

function closeCart() {
  state.cartOpen = false;
  const drawer = document.getElementById('cart-drawer');
  const overlay = document.getElementById('drawer-overlay');
  drawer.dataset.open = 'false';
  overlay.dataset.open = 'false';
  document.body.style.overflow = '';
  // Return focus
  document.getElementById('cart-toggle')?.focus();
}

// ─── Event delegation ─────────────────────────────────────────

document.addEventListener('click', (e) => {
  // Add to cart
  const addBtn = e.target.closest('[data-add-to-cart]');
  if (addBtn) {
    const id = Number(addBtn.dataset.addToCart);
    const product = products.find(p => p.id === id);
    if (!product) return;

    const alreadyInCart = state.cart.find(c => c.id === id);
    if (!alreadyInCart) {
      state.cart.push(product);
      updateCartBadge();
      announce(`${product.name} added to cart.`);
    } else {
      announce(`${product.name} is already in your cart.`);
    }

    // Temporary "Added" state on button
    const originalLabel = addBtn.getAttribute('aria-label');
    addBtn.setAttribute('aria-label', `Added: ${product.name}`);
    addBtn.innerHTML = '<span aria-hidden="true">✓</span> Added';
    addBtn.style.background = 'var(--color-success)';
    addBtn.style.color = '#fff';
    setTimeout(() => {
      addBtn.setAttribute('aria-label', originalLabel);
      addBtn.innerHTML = '<span aria-hidden="true">＋</span> Add to Cart';
      addBtn.style.background = '';
      addBtn.style.color = '';
    }, 1800);
    return;
  }

  // Remove from cart
  const removeBtn = e.target.closest('[data-remove-cart]');
  if (removeBtn) {
    const id = Number(removeBtn.dataset.removeCart);
    state.cart = state.cart.filter(c => c.id !== id);
    const product = products.find(p => p.id === id);
    updateCartBadge();
    announce(`${product?.name ?? 'Item'} removed from cart.`);
    renderCart();
    return;
  }

  // Wishlist toggle
  const wishlistBtn = e.target.closest('[data-wishlist-id]');
  if (wishlistBtn) {
    const id = Number(wishlistBtn.dataset.wishlistId);
    const product = products.find(p => p.id === id);
    const isWishlisted = state.wishlist.has(id);
    if (isWishlisted) {
      state.wishlist.delete(id);
      wishlistBtn.setAttribute('aria-pressed', 'false');
      wishlistBtn.setAttribute('aria-label', `Add to wishlist: ${product?.name}`);
      wishlistBtn.textContent = '🤍';
      announce(`${product?.name} removed from wishlist.`);
    } else {
      state.wishlist.add(id);
      wishlistBtn.setAttribute('aria-pressed', 'true');
      wishlistBtn.setAttribute('aria-label', `Remove from wishlist: ${product?.name}`);
      wishlistBtn.textContent = '❤️';
      announce(`${product?.name} added to wishlist.`);
    }
    return;
  }

  // Cart toggle
  if (e.target.closest('#cart-toggle')) {
    openCart();
    return;
  }

  // Close cart
  if (e.target.closest('#cart-close') || e.target.closest('#drawer-overlay')) {
    closeCart();
    return;
  }

  // Mobile menu
  const menuToggle = e.target.closest('#menu-toggle');
  if (menuToggle) {
    const nav = document.getElementById('primary-nav');
    const isOpen = nav.dataset.open === 'true';
    nav.dataset.open = isOpen ? 'false' : 'true';
    menuToggle.setAttribute('aria-expanded', String(!isOpen));
    return;
  }
});

// Keyboard: Escape to close drawer / mobile menu
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    if (state.cartOpen) { closeCart(); return; }
    const nav = document.getElementById('primary-nav');
    if (nav?.dataset.open === 'true') {
      nav.dataset.open = 'false';
      document.getElementById('menu-toggle')?.setAttribute('aria-expanded', 'false');
      document.getElementById('menu-toggle')?.focus();
    }
  }
});

// Focus trap for cart drawer
document.addEventListener('keydown', (e) => {
  if (!state.cartOpen || e.key !== 'Tab') return;
  const drawer = document.getElementById('cart-drawer');
  const focusable = [...drawer.querySelectorAll(
    'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
  )].filter(el => !el.disabled && el.offsetParent !== null);
  if (focusable.length === 0) return;
  const first = focusable[0];
  const last = focusable[focusable.length - 1];
  if (e.shiftKey) {
    if (document.activeElement === first) { e.preventDefault(); last.focus(); }
  } else {
    if (document.activeElement === last) { e.preventDefault(); first.focus(); }
  }
});

// ─── Countdown timer ──────────────────────────────────────────
(function startCountdown() {
  let totalSecs = 9 * 3600 + 34 * 60 + 52;
  function tick() {
    if (totalSecs <= 0) return;
    totalSecs--;
    const h = Math.floor(totalSecs / 3600);
    const m = Math.floor((totalSecs % 3600) / 60);
    const s = totalSecs % 60;
    const pad = n => String(n).padStart(2, '0');
    const hEl = document.getElementById('cd-hours');
    const mEl = document.getElementById('cd-mins');
    const sEl = document.getElementById('cd-secs');
    if (hEl) hEl.textContent = pad(h);
    if (mEl) mEl.textContent = pad(m);
    if (sEl) sEl.textContent = pad(s);
  }
  setInterval(tick, 1000);
})();

// ─── Newsletter form ───────────────────────────────────────────
document.addEventListener('DOMContentLoaded', () => {
  renderProducts();
  updateCartBadge();

  const form = document.getElementById('newsletter-form');
  if (!form) return;
  const input = form.querySelector('#newsletter-email');
  const msg = form.querySelector('#newsletter-msg');

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const val = input.value.trim();
    const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    // Reset
    input.removeAttribute('aria-invalid');
    input.removeAttribute('aria-describedby');
    msg.removeAttribute('data-type');
    msg.textContent = '';

    if (!val || !emailRe.test(val)) {
      input.setAttribute('aria-invalid', 'true');
      input.setAttribute('aria-describedby', 'newsletter-msg');
      msg.setAttribute('data-type', 'error');
      msg.textContent = 'Please enter a valid email address.';
      input.focus();
      return;
    }

    msg.setAttribute('data-type', 'success');
    msg.textContent = '🎉 You\'re in! Check your inbox for a welcome gift.';
    input.value = '';
    input.setAttribute('aria-describedby', 'newsletter-msg');
    announce('Subscription successful. Check your inbox for a welcome gift.');
  });
});
